man=json.loads((root/'交付总清单.json').read_text(encoding='utf-8'))
errors=[]
for f in man['images']:
 for field,h in [('absolute_file','png_sha256'),('absolute_jpg','jpg_sha256')]:
  p=Path(f[field])
  with Image.open(p) as im:
   if im.size!=(2000,2000) or im.mode!='RGB':errors.append(f['id']+' bad '+field)
  if hashlib.sha256(p.read_bytes()).hexdigest()!=f[h]:errors.append(f['id']+' hash '+field)
 if not (root/f['folder']/f['source']).exists():errors.append(f['id']+' missing source')
 if f['approved_for_upload'] or f['approved_for_automation']:errors.append(f['id']+' incorrect approval flag')
for p in root.rglob('*.html'):
 for ref in re.findall(r'(?:src|href)="([^"]+)"',p.read_text(encoding='utf-8')):
