from html.parser import HTMLParser
from urllib.parse import unquote
import json,hashlib,shutil,zipfile
from PIL import Image
root=Path('E:/Desktop/待上架_新图文素材库_第六批')
screen=Path('C:/Users/24243/AppData/Local/Temp/chrome-devtools-mcp-fdxNdn/screenshot.png')
shutil.copy2(screen,root/'_核验依据/审稿总览渲染检查.png')
manifest=json.loads((root/'交付总清单.json').read_text(encoding='utf-8'))
checks=[]; errors=[]
for i in manifest['images']:
 for typ,key in [('PNG','absolute_file'),('JPG','absolute_jpg')]:
  p=Path(i[key]);im=Image.open(p);im.load();h=hashlib.sha256(p.read_bytes()).hexdigest()
  ok=im.size==(2000,2000) and h==i[typ.lower()+'_sha256']
  checks.append({'id':i['id'],'format':typ,'dimensions':im.size,'sha256_match':ok})
  if not ok:errors.append(i['id']+' '+typ)
 for r in [root/i['folder']/i['source']]:
  if not r.exists():errors.append(str(r))
class Links(HTMLParser):
 def __init__(self):super().__init__();self.links=[]
 def handle_starttag(self,tag,attrs):
  for k,v in attrs:
   if k in ['href','src']:self.links.append(v)
for page in root.rglob('*.html'):
 p=Links();p.feed(page.read_text(encoding='utf-8'))
 for u in p.links:
  if u.startswith(('http:','https:','#','data:')):continue
  if not (page.parent/unquote(u.split('#')[0])).exists():errors.append('Missing link '+str(page)+' '+u)
rec=json.loads((root/'验证记录.json').read_text(encoding='utf-8'))
rec['errors']+=errors
rec['visual_review']='已目视检查15张总预览、两张新规格图、最终HOLDER303_05返修图及浏览器总览全页。颜色与规格已校正；生成壳体、纸层和比例仍须实物核样。'
rec['browser_review']={'cards':15,'images_loaded':15,'viewport_width':1365,'document_scroll_width':1365,'horizontal_overflow':False,'screenshot':'_核验依据/审稿总览渲染检查.png'}
rec['file_checks']=checks
rec['local_links_valid']=not any(e.startswith('Missing link') for e in errors)
(root/'验证记录.json').write_text(json.dumps(rec,ensure_ascii=False,indent=2),encoding='utf-8')
assert not rec['errors'], rec['errors']
archive=root.parent/(root.name+'.zip')
if archive.exists():raise RuntimeError('Archive already exists; preserve it')
with zipfile.ZipFile(archive,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=1) as z:
 for p in root.rglob('*'):
  if p.is_file():z.write(p,p.relative_to(root.parent))
with zipfile.ZipFile(archive) as z:
 bad=z.testzip();names=z.namelist()
 assert bad is None,bad
 pngs=[n for n in names if '/交付候选_2000px/' in n and n.endswith('.png')]
 jpgs=[n for n in names if '/ASIN命名JPG_交付候选/' in n and n.endswith('.jpg')]
 assert len(pngs)==15 and len(jpgs)==15,(len(pngs),len(jpgs))
print(json.dumps({'errors':errors,'png':len(pngs),'jpg':len(jpgs),'archive':str(archive),'archive_MB':round(archive.stat().st_size/1048576,1),'files':len(names),'crc':'passed'},ensure_ascii=False))
